sys_ws_operation.operation_script:
(function process(request, response) {
    var ROLES = ['production_planner', 'production_manager', 'production_supervisor', 'plant_manager', 'operations_manager'];
    var ok = gs.hasRole('admin');
    for (var i = 0; i < ROLES.length && !ok; i++) ok = gs.hasRole('x_2056099_indust_0.' + ROLES[i]);
    if (!ok) { response.setStatus(403); response.setBody({ success: false, error: 'Insufficient role for this operation' }); return; }
    var body = {};
    try { body = typeof request.body.data === 'string' ? JSON.parse(request.body.data) : (request.body.data || {}); } catch (e) { body = {}; }
    var rs = new x_2056099_indust_0.AdaptiveRescheduler(), result;
    if (body.action == 'apply') {
        result = rs.applyScenario(body.scenario_sys_id);
    } else {
        var m = new GlideRecord('x_2056099_indust_0_machine'), id = body.machine_id || body.machine_sys_id || '';
        result = id && (m.get(id) || m.get('number', id) || m.get('name', id)) ? rs.propose(m.getUniqueValue()) : { success: false, error: 'machine_id (sys_id, number or name) is required' };
    }
    if (!result.success) response.setStatus(400);
    response.setBody(result);
})(request, response);
